"css": "\n.ll-slot { --r: 8.75em; --rim: 0.75em; --lx: var(--lx-d); --ly: var(--ly-d); --fx: var(--fx-d); --fy: var(--fy-d); --z: var(--z-d); }\n.ll-layer[data-role=\"lens\"] { z-index: 5; pointer-events: none; }\n.ll-layer[data-role=\"lens\"] .ll-lens { right: auto !important; bottom: auto !important; width: calc(var(--r) * 2) !important; height: calc(var(--r) * 2) !important; border-radius: 50%; background-color: var(--4868bcaa-9a0d-4224-95ec-31860559a344); box-shadow: inset 1.5px 2px 0 color-mix(in oklab, var(--226de5f6-1cf7-462e-8dcf-7b7287f104df) 30%, transparent), inset -1px -1.5px 0 color-mix(in oklab, var(--4190f633-0121-4548-9414-2561bf6dc273) 60%, transparent), 3px 5px 8px -3px color-mix(in oklab, var(--4190f633-0121-4548-9414-2561bf6dc273) 55%, transparent), 30px 38px 54px -20px color-mix(in oklab, var(--4190f633-0121-4548-9414-2561bf6dc273) 60%, transparent); translate: calc(var(--lx) - var(--r)) calc(var(--ly) - var(--r)); }\n.ll-layer[data-role=\"paper\"] .ll-view { contain: layout; }\n.ll-layer[data-role=\"lens\"] .ll-view { top: var(--rim) !important; left: var(--rim) !important; right: var(--rim) !important; bottom: var(--rim) !important; overflow: hidden; border-radius: 50%; contain: paint; background-color: var(--ac3c074d-a4d3-4314-86fb-1ab559f81bbc); }\n.ll-layer[data-role=\"lens\"] .ll-paper { transform-origin: 0 0; translate: calc(var(--r) - var(--rim) - var(--fx) * var(--z)) calc(var(--r) - var(--rim) - var(--fy) * var(--z)); scale: var(--z); }\n.ll-layer[data-role=\"lens\"] .ll-glass { display: block !important; position: absolute; top: var(--rim); left: var(--rim); right: var(--rim); bottom: var(--rim); z-index: 6; border-radius: 50%; background-image: radial-gradient(circle at 32% 24%, color-mix(in oklab, var(--226de5f6-1cf7-462e-8dcf-7b7287f104df) 24%, transparent), transparent 40%); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--226de5f6-1cf7-462e-8dcf-7b7287f104df) 55%, transparent), inset 0 0 2.6em color-mix(in oklab, var(--462d8d28-3595-4448-938a-cb96925f1cbb) 26%, transparent); pointer-events: none; }\n.ll-layer[data-role=\"lens\"] .ll-ring { display: block !important; position: absolute; top: 0.3em; left: 0.3em; right: 0.3em; bottom: 0.3em; z-index: 7; border-radius: 50%; box-shadow: 0 0 0 0.13em var(--1b638e35-6394-45c3-98d5-6948bbf61daa); pointer-events: none; }\n/* Paid, pressed into the stock at the last stop; Pay becomes Paid in full */\n.ll-stamp { opacity: 0; visibility: hidden; }\n:scope[data-paid=\"true\"] .ll-stamp { opacity: 1; visibility: visible; }\n.ll-done { opacity: 0; }\n:scope[data-paid=\"true\"] .ll-due { opacity: 0; }\n:scope[data-paid=\"true\"] .ll-done { opacity: 1; }\n.ll-zm { display: none; }\n/* narrow desktops: the rail shares its five columns between the four stops */\n@media (min-width: 1024px) and (max-width: 1232px) {\n  .ll-groove { width: 100% !important; grid-auto-columns: minmax(0, 1fr) !important; }\n  .ll-stop { padding-left: 8px !important; padding-right: 8px !important; font-size: 15px !important; }\n}\n/* phones crop the stage to the invoice: the card and slip wait at the edge and slide over it */\n@media (max-width: 576px) {\n  .ll-slot { --r: 6.25em; --lx: var(--lx-m); --ly: var(--ly-m); --fx: var(--fx-m); --fy: var(--fy-m); --z: var(--z-m); }\n  :scope[data-at=\"reminder\"] .ll-card, :scope[data-at=\"payout\"] .ll-slip { transform: none !important; }\n  .ll-z { display: none; }\n  .ll-zm { display: inline; }\n}\n\n:scope.is-live .ll-layer[data-role=\"lens\"] .ll-lens { transition: translate 280ms cubic-bezier(0.16, 1, 0.3, 1); }\n:scope.is-live .ll-layer[data-role=\"lens\"] .ll-paper { transition: translate 280ms cubic-bezier(0.16, 1, 0.3, 1), scale 280ms cubic-bezier(0.16, 1, 0.3, 1); }\n:scope.is-live .ll-stamp { transition: opacity 280ms cubic-bezier(0.16, 1, 0.3, 1), visibility 0s linear 280ms; }\n:scope.is-live[data-paid=\"true\"] .ll-stamp { transition: opacity 280ms cubic-bezier(0.16, 1, 0.3, 1), visibility 0s; }\n:scope.is-live .ll-due, :scope.is-live .ll-done { transition: opacity 280ms cubic-bezier(0.16, 1, 0.3, 1); }\n.ll-slot.is-settling *, .ll-slot.is-settling *::before, .ll-slot.is-settling *::after { transition: none !important; }\n@media (max-width: 576px) {\n  :scope.is-live .ll-card, :scope.is-live .ll-slip { transition: transform 280ms cubic-bezier(0.16, 1, 0.3, 1); }\n}\n\n.lp-groove-btn { position: relative; isolation: isolate; color: var(--db5e3f15-6b7d-4b34-a3a4-4f20597869e0); background-color: transparent; cursor: pointer; }\n.lp-groove-btn::before { content: \"\"; position: absolute; inset: 0; z-index: -1; border-radius: inherit; background-color: var(--014831a8-af90-4fc4-affc-0e3902c2fec1); background-image: linear-gradient(100deg, var(--014831a8-af90-4fc4-affc-0e3902c2fec1), transparent 45%); box-shadow: inset 0 1px 0 color-mix(in oklab, var(--226de5f6-1cf7-462e-8dcf-7b7287f104df) 90%, transparent), inset 0 -1px 0 color-mix(in oklab, var(--462d8d28-3595-4448-938a-cb96925f1cbb) 7%, transparent), 0 0 0 0.5px color-mix(in oklab, var(--462d8d28-3595-4448-938a-cb96925f1cbb) 22%, transparent), 0 1px 0 color-mix(in oklab, var(--462d8d28-3595-4448-938a-cb96925f1cbb) 12%, transparent), 6px 5px 10px -6px color-mix(in oklab, var(--462d8d28-3595-4448-938a-cb96925f1cbb) 30%, transparent); opacity: 0; }\n.lp-groove-btn:hover { color: var(--4868bcaa-9a0d-4224-95ec-31860559a344); }\n.lp-groove-btn:active { transform: translateY(1px); }\n.lp-groove-btn[aria-pressed=\"true\"] { color: var(--4868bcaa-9a0d-4224-95ec-31860559a344); }\n.lp-groove-btn[aria-pressed=\"true\"]::before { opacity: 1; }\n.lp-groove-btn:focus-visible { outline: 2px solid var(--842d2357-1da3-45c6-ac8f-4ea3b2bf6e1b); outline-offset: -2px; }\n\n:scope.is-live .lp-groove-btn { transition: color 180ms cubic-bezier(0.16, 1, 0.3, 1), transform 120ms cubic-bezier(0.16, 1, 0.3, 1); }\n:scope.is-live .lp-groove-btn::before { transition: opacity 180ms cubic-bezier(0.16, 1, 0.3, 1); }\n\n@media (prefers-reduced-motion: reduce) { :scope *,