"js": "\nconst live = typeof window !== \"undefined\";\nconst root = this;\n// live pages pass component.component_data; the editor canvas passes the whole component\nconst raw = component_data || {};\nconst data = raw.component_data && typeof raw.component_data === \"object\" ? raw.component_data : raw;\nconst stops = Array.isArray(data.stops) ? data.stops : [];\nconst slot = root.querySelector(\".ll-slot\");\nconst buttons = Array.from(root.querySelectorAll(\".ll-stop\"));\nconst zoomNote = root.querySelector(\".ll-z\");\nconst phoneZoomNote = root.querySelector(\".ll-zm\");\nconst noteText = root.querySelector(\".ll-note\");\nconst count = Math.min(buttons.length, stops.length);\nlet index = count ? Math.min(Math.max(Number(data.start) || 0, 0), count - 1) : 0;\nconst write = (el, value) => {\n  if (el && typeof value === \"string\" && el.textContent !== value) el.textContent = value;\n};\n// the picked stop: pressed state, the stage's target and Paid at the last stop, the note\nconst mark = (i) => {\n  index = i;\n  const stop = stops[i] || {};\n  buttons.forEach((button, k) => {\n    button.setAttribute(\"aria-pressed\", k === i ? \"true\" : \"false\");\n    button.setAttribute(\"tabindex\", k === i ? \"0\" : \"-1\");\n  });\n  const paid = count > 1 && i === count - 1;\n  root.setAttribute(\"data-at\", String(stop.target || \"\"));\n  root.setAttribute(\"data-paid\", paid ? \"true\" : \"false\");\n  // Pay and Paid in full share a place: only the one on show is read out\n  root.querySelectorAll(\".ll-due\").forEach((el) => el.setAttribute(\"aria-hidden\", paid ? \"true\" : \"false\"));\n  root.querySelectorAll(\".ll-done\").forEach((el) => el.setAttribute(\"aria-hidden\", paid ? \"false\" : \"true\"));\n  write(zoomNote, stop.zl);\n  write(phoneZoomNote, stop.zml);\n  write(noteText, stop.note);\n};\nif (count) mark(index);\nif (!live || !count || !slot) return;\n\nconst keys = (groove, buttons, count, go, escapeToFirst) => (event) => {\n  const at = buttons.indexOf(document.activeElement);\n  if (at < 0 || at >= count) return;\n  const step = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[event.key];\n  let next = null;\n  if (step) next = (at + step + count) % count;\n  else if (event.key === \"Home\") next = 0;\n  else if (event.key === \"End\") next = count - 1;\n  else if (event.key === \"Escape\" && escapeToFirst) next = 0;\n  if (next === null) return;\n  event.preventDefault();\n  go(next, true);\n};\n\nconst paper = root.querySelector('.ll-layer[data-role=\"paper\"] .ll-paper');\nconst lens = root.querySelector('.ll-layer[data-role=\"lens\"] .ll-lens');\nconst phone = () => window.matchMedia(\"(max-width: 576px)\").matches;\n// a target's centre on the paper, in stage ems, from layout and its piece's own rotation\n// (offsets and `left`/`top` ignore transforms, so a card still sliding in measures where it lands)\nconst locate = (stop, size) => {\n  if (!paper) return null;\n  const target = String(stop.target || \"\");\n  if (target.indexOf(\"%\") >= 0) {\n    const parts = target.split(/[\\s,]+/).filter(Boolean).map(parseFloat);\n    if (parts.length === 2 && parts.every((n) => isFinite(n))) {\n      return { x: (paper.offsetWidth * parts[0]) / 100 / size, y: (paper.offsetHeight * parts[1]) / 100 / size };\n    }\n    return null;\n  }\n  const el = Array.from(paper.querySelectorAll(\"[data-target]\")).find((n) => n.getAttribute(\"data-target\") === target);\n  if (!el) return null;\n  const piece = el.closest(\".ll-piece\") || paper;\n  let x = el.offsetWidth / 2;\n  let y = el.offsetHeight / 2;\n  for (let n = el; n && n !== piece; n = n.offsetParent) {\n    x += n.offsetLeft;\n    y += n.offsetTop;\n  }\n  const style = getComputedStyle(piece);\n  const angle = ((parseFloat(style.rotate) || 0) * Math.PI) / 180;\n  const w = piece.offsetWidth;\n  const h = piece.offsetHeight;\n  const left = piece === paper ? 0 : parseFloat(style.left) || 0;\n  const top = piece === paper ? 0 : parseFloat(style.t