component_data_script:
rows = props.get("stops") or []
if isinstance(rows, str):
	try:
		rows = json.loads(rows)
	except Exception:
		rows = [line for line in rows.split("\n") if line.strip()]
if not isinstance(rows, list):
	rows = []

# where each built target sits on the paper, in stage ems, as the live script measures it once
# the fonts are in (1280 and 1440 wide; 390 for phones). The first paint and the editor canvas
# use these, and the live script re-measures to the same place, so the lens never jumps.
desk_spots = {"items": [25.81, 18.73], "reminder": [34.45, 12.6], "payment": [7.91, 34.97], "payout": [36.3, 33.82]}
phone_spots = {"items": [22.45, 22.13], "reminder": [6.3, 14.11], "payment": [7.16, 37.29], "payout": [8.1, 18.25]}


def num(value, fallback):
	try:
		return float(str(value).replace("x", "").replace("%", "").strip())
	except Exception:
		return fallback


def fmt(value):
	text = str(round(value, 3))
	if text.endswith(".0"):
		text = text[:-2]
	return text


def clamp(value, low, high):
	return min(max(value, low), high)


def spot(target, table, width, height, num):
	if target in table:
		return table[target]
	parts = str(target).replace(",", " ").split()
	if "%" in str(target) and len(parts) == 2:
		return [width * num(parts[0], 50) / 100, height * num(parts[1], 50) / 100]
	return [width / 2, height / 2]


def place(xy, width, height, lo, clamp):
	return [clamp(xy[0], lo, width - lo), clamp(xy[1], lo, height - lo)]


stops = []
for raw in rows:
	parts = [part.strip() for part in str(raw).split("|")]
	if not parts or not parts[0]:
		continue
	target = parts[1] if len(parts) > 1 and parts[1] else "items"
	z = clamp(num(parts[2] if len(parts) > 2 else 2, 2), 1, 4)
	zm = clamp(num(parts[3] if len(parts) > 3 and parts[3] else z, z), 1, 4)
	stops.append({"label": parts[0], "target": target, "z": z, "zm": zm, "note": parts[4] if len(parts) > 4 else ""})

start = 0
if stops:
	start = int(clamp(num(props.get("start"), 1), 1, len(stops))) - 1
first = stops[start] if stops else {"target": "items", "z": 2.2, "zm": 2.6, "note": ""}
focus_d = spot(first["target"], desk_spots, 46, 42, num)
focus_m = spot(first["target"], phone_spots, 26, 43.5, num)
lens_d = place(focus_d, 46, 42, 9, clamp)
lens_m = place(focus_m, 26, 43.5, 6.5, clamp)
component.lx_d = fmt(lens_d[0]) + "em"
component.ly_d = fmt(lens_d[1]) + "em"
component.fx_d = fmt(focus_d[0]) + "em"
component.fy_d = fmt(focus_d[1]) + "em"
component.z_d = fmt(first["z"])
component.lx_m = fmt(lens_m[0]) + "em"
component.ly_m = fmt(lens_m[1]) + "em"
component.fx_m = fmt(focus_m[0]) + "em"
component.fy_m = fmt(focus_m[1]) + "em"
component.z_m = fmt(first["zm"])
component.at = first["target"]
paid = len(stops) > 1 and start == len(stops) - 1
component.paid = "true" if paid else "false"
component.note_z = fmt(first["z"]) + "x"
component.note_zm = fmt(first["zm"]) + "x"
component.note_text = first["note"]
component.stops = []
for i in range(len(stops)):
	component.stops.append({"label": stops[i]["label"], "i": str(i), "pressed": "true" if i == start else "false", "tab": "0" if i == start else "-1"})

# the invoice lines (Item | Qty | Rate | Amount); the middle line's amount is the items target
currency = str(props.get("currency") or "$")
line_rows = props.get("lines") or []
if isinstance(line_rows, str):
	try:
		line_rows = json.loads(line_rows)
	except Exception:
		line_rows = [line for line in line_rows.split("\n") if line.strip()]
if not isinstance(line_rows, list):
	line_rows = []
lines = []
total = 0
counted = True
for raw in line_rows:
	parts = [part.strip() for part in str(raw).split("|")]
	if not parts or not parts[0]:
		continue
	amount = parts[3] if len(parts) > 3 else ""
	try:
		total = total + float(amount.replace(",", "").replace(currency, ""))
	except Exception:
		counted = False
	lines.append({"item": parts[0], "qty": parts[1] if len(parts) > 1 else "", "rate": parts[2] if len(parts) > 2 else "", "amount": amount, "target": ""})
if lines:
	lines[len(lines) // 2]["target"] = "items"


def money(value, currency):
	cents = int(round(value * 100))
	whole = str(cents // 100)
	frac = str(cents % 100)
	if len(frac) < 2:
		frac = "0" + frac
	groups = []
	while len(whole) > 3:
		groups.insert(0, whole[-3:])
		whole = whole[:-3]
	groups.insert(0, whole)
	return currency + ",".join(groups) + "." + frac


total_text = money(total, currency) if lines and counted else None
# one template, two layers: the paper itself, and the magnified copy inside the lens
due_hidden = "true" if paid else "false"
done_hidden = "false" if paid else "true"
component.layers = [
	{"role": "paper", "hidden": "false", "lines": lines, "total": total_text, "due_hidden": due_hidden, "done_hidden": done_hidden},
	{"role": "lens", "hidden": "true", "lines": lines, "total": total_text, "due_hidden": due_hidden, "done_hidden": done_hidden},
]
component.component_data = {
	"start": start,
	"stops": [
		{"target": s["target"], "z": s["z"], "zm": s["zm"], "zl": fmt(s["z"]) + "x", "zml": fmt(s["zm"]) + "x", "note": s["note"]}
		for s in stops
	],
}
